  2102→///
  2103→/// This test verifies that 3D Gaussian covariances are correctly projected to 2D screen space
  2104→/// using the EWA splatting formula: Σ₂d = J * W * Σ * W^T * J^T
  2105→/// where:
  2106→/// - Σ is the 3D covariance matrix from scale and rotation
  2107→/// - W is the world-to-camera rotation matrix
  2108→/// - J is the Jacobian of perspective projection
  2109→#[test]
  2110→fn tc_ras_010_3d_to_2d_covariance_projection() {
  2111→    use sugar_rs::diff::covariance_grad::project_covariance_2d;
  2112→    use sugar_rs::core::perspective_jacobian;
  2113→
  2114→    const TOLERANCE: f32 = 0.05; // 5% as specified
  2115→
  2116→    println!("\n=== TC-RAS-010: 3D to 2D Covariance Projection ===\n");
  2117→
