  2119→    // For an isotropic Gaussian with scale s, the 2D projection should also be isotropic
  2120→    {
  2121→        println!("Test 1 - Isotropic Gaussian projection:");
  2122→
  2123→        // Camera parameters
  2124→        let fx = 500.0;
  2125→        let fy = 500.0;
  2126→        let camera_rotation = Matrix3::identity(); // No camera rotation
  2127→
  2128→        // Gaussian at depth 5.0 with uniform scale
  2129→        let point_cam = Vector3::new(0.0, 0.0, 5.0);
  2130→        let log_scale = Vector3::new(-1.0, -1.0, -1.0); // Uniform scale: exp(-1.0) ≈ 0.368
  2131→        let gaussian_rotation = Matrix3::identity(); // No Gaussian rotation
  2132→
  2133→        // Compute projected 2D covariance
  2134→        let jacobian = perspective_jacobian(&point_cam, fx, fy);
  2135→        let cov_2d = project_covariance_2d(&camera_rotation, &jacobian, &gaussian_rotation, &log_scale);
  2136→
  2137→        println!("  3D log-scale: ({:.2}, {:.2}, {:.2})", log_scale.x, log_scale.y, log_scale.z);
  2138→        println!("  Point in camera space: ({:.1}, {:.1}, {:.1})", point_cam.x, point_cam.y, point_cam.z);
  2139→        println!("  2D covariance:");
  2140→        println!("    [{:.6}, {:.6}]", cov_2d[(0, 0)], cov_2d[(0, 1)]);
  2141→        println!("    [{:.6}, {:.6}]", cov_2d[(1, 0)], cov_2d[(1, 1)]);
  2142→
  2143→        // For isotropic Gaussian at center (x=0, y=0), the projection should also be isotropic
  2144→        // Analytical expectation: diagonal elements should be equal, off-diagonal should be ~0
  2145→        let scale_3d = (-1.0_f32).exp(); // exp(-1.0)
  2146→        let z = point_cam.z;
  2147→
  2148→        // Expected 2D variance from perspective projection
  2149→        // σ_2d ≈ (f/z)² * σ_3d²
  2150→        let expected_var = (fx / z).powi(2) * scale_3d.powi(2);
  2151→
  2152→        println!("  Expected 2D variance: {:.6}", expected_var);
  2153→        println!("  Actual diagonal: ({:.6}, {:.6})", cov_2d[(0, 0)], cov_2d[(1, 1)]);
  2154→
  2155→        // Verify diagonal elements match expected variance within 5%
  2156→        let error_xx = ((cov_2d[(0, 0)] - expected_var) / expected_var).abs();
  2157→        let error_yy = ((cov_2d[(1, 1)] - expected_var) / expected_var).abs();
  2158→
  2159→        println!("  Error in diagonal elements: ({:.4}, {:.4})", error_xx, error_yy);
  2160→
  2161→        assert!(error_xx < TOLERANCE,
  2162→            "2D covariance xx element error too large: {:.4} > {:.4}", error_xx, TOLERANCE);
  2163→        assert!(error_yy < TOLERANCE,
  2164→            "2D covariance yy element error too large: {:.4} > {:.4}", error_yy, TOLERANCE);
  2165→
  2166→        // Off-diagonal should be nearly zero for centered isotropic Gaussian
  2167→        assert!(cov_2d[(0, 1)].abs() < 1e-6,
  2168→            "2D covariance should be diagonal for centered isotropic Gaussian");
