  2170→        println!("  ✓ Isotropic Gaussian projects correctly\n");
  2171→    }
  2172→
  2173→    // Test 2: Anisotropic Gaussian with rotation
  2174→    // Verify that anisotropic Gaussians project with correct orientation and aspect ratio
  2175→    {
  2176→        println!("Test 2 - Anisotropic Gaussian projection:");
  2177→
  2178→        // Camera parameters
  2179→        let fx = 500.0;
  2180→        let fy = 500.0;
