  2193→        println!("  Point in camera space: ({:.1}, {:.1}, {:.1})", point_cam.x, point_cam.y, point_cam.z);
  2194→        println!("  2D covariance:");
  2195→        println!("    [{:.6}, {:.6}]", cov_2d[(0, 0)], cov_2d[(0, 1)]);
  2196→        println!("    [{:.6}, {:.6}]", cov_2d[(1, 0)], cov_2d[(1, 1)]);
