  2380→/// TC-RAS-011: Anisotropic Gaussian Projection
  2381→///
  2382→/// Pass Criteria:
  2383→/// - Major/minor axis lengths within 5% of expected
  2384→/// - Orientation angle within 2° of expected
  2385→///
  2386→/// This test verifies that elongated (anisotropic) Gaussians project correctly at various orientations.
  2387→/// We verify that the major and minor axis lengths and orientation angles match analytical expectations.
  2388→#[test]
  2389→fn tc_ras_011_anisotropic_gaussian_projection() {
  2390→    use sugar_rs::diff::covariance_grad::project_covariance_2d;
  2391→    use sugar_rs::core::perspective_jacobian;
  2392→
  2393→    const LENGTH_TOLERANCE: f32 = 0.05; // 5% as specified
  2394→    const ANGLE_TOLERANCE_DEG: f32 = 2.0; // 2 degrees as specified
  2395→
  2396→    println!("\n=== TC-RAS-011: Anisotropic Gaussian Projection ===\n");
  2397→
  2398→    // Helper function to compute eigenvalues and orientation angle from 2D covariance
  2399→    fn analyze_2d_covariance(cov: &nalgebra::Matrix2<f32>) -> (f32, f32, f32) {
  2400→        // Extract 2x2 matrix elements
  2401→        let a = cov[(0, 0)];
  2402→        let b = cov[(0, 1)];
  2403→        let c = cov[(1, 1)];
  2404→
  2405→        // Compute eigenvalues: λ = (trace ± sqrt(trace² - 4*det)) / 2
  2406→        let trace = a + c;
  2407→        let det = a * c - b * b;
  2408→        let discriminant = (trace * trace - 4.0 * det).max(0.0).sqrt();
  2409→
  2410→        let lambda_major = (trace + discriminant) / 2.0; // Larger eigenvalue
  2411→        let lambda_minor = (trace - discriminant) / 2.0; // Smaller eigenvalue
  2412→
  2413→        // Major and minor axis lengths (standard deviations, not variances)
  2414→        let major_axis = lambda_major.sqrt();
  2415→        let minor_axis = lambda_minor.sqrt();
  2416→
  2417→        // Orientation angle: angle of the major axis from the x-axis
  2418→        // For a symmetric 2x2 covariance matrix [a, b; b, c], the angle of the principal axis is:
  2419→        // angle = 0.5 * atan2(2*b, a - c)
  2420→        // This gives the angle where the matrix is diagonalized
  2421→        let angle_rad = if b.abs() > 1e-8 {
  2422→            0.5 * (2.0 * b).atan2(a - c)
  2423→        } else if a > c {
  2424→            0.0 // Major axis along x
  2425→        } else {
  2426→            std::f32::consts::PI / 2.0 // Major axis along y
  2427→        };
  2428→
  2429→        (major_axis, minor_axis, angle_rad)
  2430→    }
  2431→
  2432→    // Test 1: Elongated Gaussian aligned with X-axis (0° rotation)
  2433→    {
  2434→        println!("Test 1 - Elongated Gaussian aligned with X-axis (0°):");
  2435→
  2436→        let fx = 500.0;
