  2439→
  2440→        // Gaussian at depth 8.0, elongated along X-axis (3:1 ratio)
  2441→        let point_cam = Vector3::new(0.0, 0.0, 8.0);
  2442→        let log_scale = Vector3::new(-0.5, -1.6, -1.6); // X: exp(-0.5)≈0.606, Y/Z: exp(-1.6)≈0.202
  2443→        let gaussian_rotation = Matrix3::identity(); // No rotation
  2444→
  2445→        // Compute projected 2D covariance
