        let (_img, _d_colors, _d_opacity_logits, _d_positions, d_log_scales, _d_rot_vecs, _d_bg) =
            render_full_color_grads(&gaussians, &camera, &d_image, &background, false);

        // Test gradient for first Gaussian (X component)
