        let pixel = pixels[center_idx];

        println!("  Rendered pixel: ({:.4}, {:.4}, {:.4})", pixel.x, pixel.y, pixel.z);

        // Both colors should be present
        assert!(pixel.x > 0.0, "Red should be visible");
