        println!("  ✓ All gradients within relaxed tolerance (< {:.0e})", TOLERANCE_RELAXED);
        println!("  ✓ {}/3 gradients within strict tolerance (< {:.0e})\n", strict_count, TOLERANCE_STRICT);
